// ── The walk ─────────────────────────────────────────────────────────────────

// gate is one run of vetOverlay.
type gate struct {
	ctx     context.Context //nolint:containedctx // one run of the gate, never stored
	root    string          // the limit, absolute, symbolic links resolved
	lim     gateLimits
	visited map[string]bool // directories entered, by real path
	count   int             // kustomizations read
	read    int64           // bytes read
	bases   []string        // the directories the kustomization being read pulls in
	limit   string          // what the limit is called in a reason
	cache   *gateCache
}

// gateCache remembers, for the whole pass of a scan, the directories whose
// kustomization and everything it pulls in were judged local, so that overlays
// that share a base read it once. Only a verdict of OK is kept, and only once the
// whole overlay is OK: a directory met while a cycle was still open is not known
// to be fine before that. A nil cache remembers nothing.
type gateCache struct {
	mu sync.Mutex
	ok map[string]bool
}

func (c *gateCache) has(real string) bool {
	if c == nil {
		return false
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.ok[real]
}

func (c *gateCache) add(dirs map[string]bool) {
	if c == nil {
		return
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.ok == nil {
		c.ok = map[string]bool{}
	}
	for d := range dirs {
		c.ok[d] = true
	}
}

// gateRun is what a caller that asks about many overlays of one scan adds.
type gateRun struct {
	cache *gateCache
	// limit is how the limit of the paths is called in a reason: "the scanned
	// folder" or "the repository" (the default).
	limit string
}

// gateSite is where a value was read: file is the file it is in (relative to
// the limit), dir the directory its references are relative to (the one of the
// kustomization, also for a plugin file), depth how far below the first overlay.
type gateSite struct {
	file  string
	dir   string
	depth int
}

func (s gateSite) remote(field, ref, reason string) gateVerdict {
	return gateVerdict{Kind: gateRemote, File: s.file, Field: field, Ref: ref, Reason: reason}
}

func (s gateSite) unchecked(field, ref, reason string) gateVerdict {
	return gateVerdict{Kind: gateUnchecked, File: s.file, Field: field, Ref: ref, Reason: reason}
}

// vetOverlay reads the overlay directory (absolute) and everything it pulls in,
// inside root (absolute; the gate resolves symbolic links itself).
func vetOverlay(ctx context.Context, root, overlay string, lim gateLimits) gateVerdict {
	return vetOverlayIn(ctx, root, overlay, lim, gateRun{})
}

// vetOverlayIn is vetOverlay for one pass of a scan.
func vetOverlayIn(ctx context.Context, root, overlay string, lim gateLimits, run gateRun) gateVerdict {
	if run.limit == "" {
		run.limit = "the repository"

// anything else, or a git directory that does not point back is refused: git
// was then told where the work tree is, rather than finding it.
func gitDirIsHere(root string) bool {
	dotGit := filepath.Join(root, ".git")
	info, err := os.Lstat(dotGit)
	if err != nil {
		return false
	}
	if info.IsDir() {
		return true
	}
	if !info.Mode().IsRegular() {
		return false
	}
	line, ok := readGitFile(dotGit)
	gitDir, found := strings.CutPrefix(line, "gitdir: ")
	if !ok || !found {
		return false
	}
	if !filepath.IsAbs(gitDir) {
		gitDir = filepath.Join(root, gitDir)
	}
	back, ok := readGitFile(filepath.Join(gitDir, "gitdir"))
	if !ok {
		return false
	}
	if !filepath.IsAbs(back) {
		back = filepath.Join(gitDir, back)
	}
	a, errA := filepath.EvalSymlinks(back)
	b, errB := filepath.EvalSymlinks(dotGit)
	return errA == nil && errB == nil && a == b
}

// readGitFile reads the one line of a small regular file.
func readGitFile(p string) (string, bool) {
	info, err := os.Lstat(p)
	if err != nil || !info.Mode().IsRegular() || info.Size() > maxGitFile {
		return "", false
	}
	data, err := os.ReadFile(p) //nolint:gosec // a .git file of the repository being scanned
	if err != nil {
		return "", false
	}
	return strings.TrimSpace(string(data)), true
}

// renderer runs one tool in the repository, the way every other tool runs:
// in the target for a binary; for an image, with the scope's mount read-only
// at /scan and the target inside it as the working directory.
func renderer(scope renderScope, tool ToolSpec, defaultImage, binary string, args ...string) toolCmd {
	// helm gets them on lint and on template alike: only the flags the two
	// share (--values, --set…) make sense there.
	args = afterSubcommand(args, tool.Args)
	if tool.Source != ToolSourceContainer {
		name := tool.Binary
		if name == "" {
			name = binary
		}
		cmd := toolCmd{Name: name, Args: args, Dir: scope.target}
		if scope.offline {
			cmd.Env = offlineEnviron(os.Environ())
		}
		return cmd
	}
	return containerRun{
		Flags:   []string{"-v", scope.mount + ":" + containerScanPath + ":ro", "-w", scope.workdir()},
		Image:   orDefault(tool.Image, defaultImage),
		Argv:    args,
		Offline: scope.offline,
	}.cmd()
}

func orDefault(v, def string) string {
	if v == "" {
		return def
	}
	return v
}

// renderRepro is the Repro line of a renderer run on target (a chart or an
// overlay directory), run from the scanned directory like the scan did. The
// user's arguments are left out: they may hold a secret (--set password=REDACTED
func renderRepro(tool ToolSpec, name, sub, target string) (string, ToolSource) {
	return localRepro(tool, name, []string{sub}, target)
}

func helmArgs(scope renderScope, chart string, tool ToolSpec, sub string) toolCmd {
	return renderer(scope, tool, DefaultHelmImage, "helm", sub, asPathArg(chart))
}

func kustomizeArgs(scope renderScope, dir string, tool ToolSpec) toolCmd {
	return renderer(scope, tool, DefaultKustomizeImage, "kustomize", "build", asPathArg(dir))
}

// asPathArg is dir as a positional argument of helm or kustomize. The folder's
// name comes from the repository being scanned, and two kinds of name are not
// read as the local folder it is (DEVDESK-763): one that starts with "-"
// (--load-restrictor=LoadRestrictionsNone, -x) is read as an option, and
// kustomize reads an ordinary one such as github.com/org/repo or
// git@host:o/r as a remote git base and runs git fetch even when the folder
// exists. "./" makes every relative folder a local path whatever the tool and
// wherever the user's own arguments land. "." and an absolute path already are
// one, and a name that already starts with "./" is left alone. Only the
// argument is changed: the findings, their steps and the Repro keep the
// folder's own name.
func asPathArg(dir string) string {
	if dir == "." || strings.HasPrefix(dir, "./") || filepath.IsAbs(dir) || strings.HasPrefix(dir, "/") {
		return dir
	}
	return "./" + dir
}

// kubeconformStdinArgs validates what arrives on stdin. A container gets -i
// and no repository mount: it reads nothing but its input and its cache.
func kubeconformStdinArgs(rendered []byte, tool ToolSpec, opts KubeconformOptions) toolCmd {
	flags := kubeconformFlags(tool, opts)
	if tool.Source != ToolSourceContainer {
		return toolCmd{Name: kubeconformBinary(tool), Args: append(flags, "-"), Stdin: rendered}
	}
	engineArgs := []string{"-i"}
	if opts.CacheDir != "" {
		engineArgs = append(engineArgs, "-v", opts.CacheDir+":"+kubeconformCacheMount)
	}
	return containerRun{
		Flags: engineArgs, Image: kubeconformImage(tool.Image), Argv: append(flags, "-"), Stdin: rendered,
	}.cmd()
}

// k8sValidation is one schema stage over one repository: the tools it has,
// what it validates against, and the report it fills in.
type k8sValidation struct {
	target string
	// scope is where helm and kustomize run, resolved once per stage.
	scope renderScope
	// gateRoot is the limit of the paths the native kustomize gate follows,
	// resolved once and only when a native kustomize is about to be gated.
	gateRoot    string
	gateRun     gateRun
	kubeconform ToolSpec
	opts        KubeconformOptions
	report      *KubeconformReport
}

// available reports whether an optional renderer was resolved at all.
func available(tool ToolSpec) bool {
	return tool.Source != ToolSourceNone && tool.Source != ""
}

// renderCharts lints, renders and validates each chart. Without helm, every
// chart is reported as not rendered.
	}
	return nil
}

// gateScope is the limit of the paths the kustomize gate follows, the git
// repository holding the target or the target itself without one, and what the
// gate remembers across the overlays of this scan. git is asked once, the first
// time a native kustomize is gated.
func (v *k8sValidation) gateScope(ctx context.Context) (string, gateRun) {
	if v.gateRoot == "" {
		scope := resolveRenderScope(ctx, v.target)
		v.gateRoot = scope.mount
		v.gateRun = gateRun{cache: &gateCache{}, limit: "the repository"}
		if scope.rel == "" {
			v.gateRun.limit = "the scanned folder"
		}
	}
	return v.gateRoot, v.gateRun
}

// markRemoteBlocked gives a K8S-RENDER finding the words of a remote base the
// cut network refused, whether kustomize said so or the gate did. A copied
// `kustomize build` would run the refused fetch again, with the user's ssh agent
// and proxy, on a repository that is not trusted, so there is no Repro.
func markRemoteBlocked(f *Finding) {
	f.Title = remoteBlockedHeadline
	f.Resolution = remoteBlockedResolution
	f.Repro = ""
}

// gateFinding is the K8S-RENDER finding of an overlay the gate refused, so that
// kustomize was not started: a reference that is not local gets the finding of a
// blocked remote base, an overlay that could not be judged one of its own.
func gateFinding(dir, file string, v gateVerdict, from ToolSource) Finding {
	if v.Kind == gateRemote {
		f := renderFailure(SourceKustomize, "kustomize", file, "Overlay does not build", from,
			renderSteps(SourceKustomize, dir, from, "", true), "", errors.New(remoteMessage(v)))
		markRemoteBlocked(&f)
		return f
	}
	f := renderFailure(SourceKustomize, "kustomize", file, "Overlay not built", from,
		uncheckedOverlaySteps(dir, v.Reason), "", errors.New(uncheckedMessage(dir, v)))
	f.Title = uncheckedOverlayHeadline
	f.Resolution = uncheckedResolution
	return f
}

// remoteMessage says where the reference is, what it is and why it is refused,
// each name as %q: the text is the repository's own.
func remoteMessage(v gateVerdict) string {
	return fmt.Sprintf("DevDesk did not run kustomize: the field %q of %q holds %q, which is not a path of this repository (%s).",
		clip(v.Field), clip(v.File), clip(v.Ref), clip(v.Reason))
}

// uncheckedMessage says what could not be checked, in which file and field.
func uncheckedMessage(dir string, v gateVerdict) string {
	msg := fmt.Sprintf("DevDesk did not run kustomize: the references of the overlay %q could not be checked", clip(dir))
	if v.File != "" {
		msg += fmt.Sprintf(", in %q", clip(v.File))
	}
	if v.Field != "" {
		msg += fmt.Sprintf(" (field %q)", clip(v.Field))
	}
	return msg + ": " + clip(v.Reason) + "."
}

// validateRendered runs kubeconform over rendered YAML and points each
// finding back at the file it came from. A rendered line is not a line of
// any file in the repository, so these findings carry none.
func (v *k8sValidation) validateRendered(ctx context.Context, rendered []byte, dialect string, origin func(kind, name string) string) error {
	if len(bytes.TrimSpace(rendered)) == 0 {
		return nil
	}
	cmd := kubeconformStdinArgs(rendered, v.kubeconform, v.opts)
	log.Printf("Running: %s", cmd.Loggable())
	out, err := runner.Run(ctx, cmd, nil)
	if err := kubeconformFailure(out, err); err != nil {
		return err
	}
	noFile := func(string) ([]byte, error) { return nil, errors.New("rendered, not a file") }
	findings, skipped, err := parseKubeconformReport(out, v.opts.KubernetesVersion, noFile, origin, dialect)
	if err != nil {
		return err
	}
	v.report.SkippedCustom += skipped
	for i := range findings {
		findings[i].IaCType = dialect
	}
	v.report.Findings = append(v.report.Findings, findings...)
	return nil
}

// helmLint runs helm lint and returns its warnings and errors. helm exits 1
// when a chart fails; its messages are still the answer. A run that printed
// nothing parseable is logged and yields nothing — the render that follows
// will say whether the chart is usable.
func helmLint(ctx context.Context, scope renderScope, chart string, tool ToolSpec) []Finding {
	cmd := helmArgs(scope, chart, tool, "lint")
	log.Printf("Running: %s", cmd.Loggable())
	out, err := runner.Run(ctx, cmd, nil)
	findings, recognised := parseHelmLint(out, chart, scope)
	if err != nil && !recognised {
		log.Printf("ERROR [scan/helm] lint %s: %v", logWord(chart), logErr(err))
	}
	repro, from := renderRepro(tool, "helm", "lint", chart)
	for i := range findings {
		findings[i].Repro, findings[i].RanFrom = repro, from
	}
	return findings
}

// parseHelmLint turns helm lint's text into findings. The second result says
// the output was helm lint's at all.
//
// A message's path is usually relative to the chart ("templates/cm.yaml"),
// but not always: the missing-dependency warning names the chart directory
// absolutely — "/scan/charts/broken" in a container, measured on helm 4.3.0.
// Both are brought back to a path relative to the target.
func parseHelmLint(out []byte, chart string, scope renderScope) ([]Finding, bool) {
	file := func(p string) string { return helmLintPath(p, chart, scope) }
	var findings []Finding
	recognised := false
	sc := bufio.NewScanner(bytes.NewReader(out))
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		switch {
		case strings.HasPrefix(line, "==> Linting"):
			recognised = true
		case strings.HasPrefix(line, "Error "):
			// Printed instead of the messages when the chart could not be
			// loaded at all.
			recognised = true
			findings = append(findings, helmLintFinding(chart, chart, SeverityHigh, strings.TrimPrefix(line, "Error ")))
		default:
			m := helmLintLine.FindStringSubmatch(line)
			if m == nil {
				continue
			}
			recognised = true
			switch m[1] {
			case "ERROR":
				findings = append(findings, helmLintFinding(chart, file(m[2]), SeverityHigh, m[3]))
			case "WARNING":
				findings = append(findings, helmLintFinding(chart, file(m[2]), SeverityLow, m[3]))
			}
		}
	}
	return findings, recognised
}

// helmLintPath resolves a path helm lint printed to one relative to the
// target. In a container the target is the scope's working directory, which is
// /scan itself unless the git repository around the target is mounted.
func helmLintPath(p, chart string, scope renderScope) string {
	p = strings.TrimSuffix(p, "/")
	switch {
	case p == containerScanPath || strings.HasPrefix(p, containerScanPath+"/"):
		if rel, err := filepath.Rel(filepath.FromSlash(scope.workdir()), filepath.FromSlash(p)); err == nil {
			return filepath.ToSlash(rel)
		}
		return p
	case filepath.IsAbs(p):
		if rel, err := filepath.Rel(scope.target, p); err == nil && !strings.HasPrefix(rel, "..") {
			return filepath.ToSlash(rel)
		}
		return filepath.ToSlash(p)
	default:
		return path.Join(chart, p)
	}
}

func helmLintFinding(chart, file string, severity SeverityLevel, msg string) Finding {
	return Finding{
		Steps:       helmLintSteps(file, chart),
		ID:          HelmLintID,
		Title:       msg,
		Description: "helm lint reported this about the chart.",
		Message:     msg,
		Severity:    severity,
		Source:      SourceHelm,
		File:        file,
		IaCType:     "helm",
	}
}

func hasError(findings []Finding) bool {
	for _, f := range findings {
		if f.Severity == SeverityHigh {
			return true
		}
	}
	return false
}

// renderFailure is a chart or an overlay that could not be rendered: nothing
// in it was validated, and `helm install` or `kubectl apply -k` would fail the
// same way.
//
// steps and repro are what the caller wrote for it (renderSteps, localRepro);
// from is where the renderer ran.
func renderFailure(source, dialect, file, title string, from ToolSource, steps []string, repro string, err error) Finding {

}

// within reports whether p is root or below it, lexically.
func within(root, p string) bool {
	rel, err := filepath.Rel(root, p)
	return err == nil && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
}

// isMissing reports whether err says a path is not there (or has a file where a
// directory should be): nothing for kustomize to load, so nothing to fetch.
func isMissing(err error) bool {
	return err != nil && (errors.Is(err, fs.ErrNotExist) || errors.Is(err, syscall.ENOTDIR))
}

// rel is p relative to the limit, with forward slashes.
func (g *gate) rel(p string) string {
	r, err := filepath.Rel(g.root, p)
	if err != nil {
		return filepath.ToSlash(p)
	}
	return filepath.ToSlash(r)
}

// dir judges the kustomization of one directory (a real path inside the limit)
// and, through it, everything it pulls in. A directory with none holds nothing
// to follow.
func (g *gate) dir(real string, depth int) gateVerdict {
	if g.visited[real] || g.cache.has(real) {
		return gateVerdict{}
	}
	g.visited[real] = true
	where := gateSite{file: g.rel(real), dir: real, depth: depth}
	switch {
	case g.ctx.Err() != nil:
		return where.unchecked("", "", "the check was cancelled")
	case depth > g.lim.Depth:
		return where.unchecked("", "", fmt.Sprintf("overlays are nested more than %d levels deep", g.lim.Depth))
	}
	file, v := g.kustomizationFile(real)
	if file == "" {
		return v
	}
	if g.count++; g.count > g.lim.Visited {
		return where.unchecked("", "", fmt.Sprintf("more than %d kustomizations are pulled in", g.lim.Visited))
	}
	site := gateSite{file: g.rel(file), dir: real, depth: depth}
	bases, v := g.kustomization(file, site)
	if v.Kind != gateOK {
		return v
	}
	// The kustomization is out of memory before its bases are read in turn.
	for _, base := range bases {
		if v := g.dir(base, depth+1); v.Kind != gateOK {
			return v
		}
	}
	return gateVerdict{}
}

// kustomization judges the file of a kustomization. The directories it pulls in
// are returned, not read: this function's YAML is released first.
func (g *gate) kustomization(file string, site gateSite) ([]string, gateVerdict) {
	// The kustomization file may itself be a link: what is read is what it names.
	if target, err := filepath.EvalSymlinks(file); err != nil || !within(g.root, target) {
		return nil, site.unchecked("", "", "the kustomization file leaves "+g.limit+" through a symbolic link")
	}
	node, reason := g.readYAML(file)
	if reason == reasonNoDocument {
		reason = "the kustomization file is empty"
	}
	if reason != "" {
		return nil, site.unchecked("", "", reason)
	}
	g.bases = nil
	v := g.applyMap(mapOf(kustomizationRules), node, "", site, true)
	bases := g.bases
	g.bases = nil
	return bases, v
}

// kustomizationFile is the kustomization file of dir, "" when there is none, or a
// verdict when there are several.
func (g *gate) kustomizationFile(dir string) (string, gateVerdict) {
	var found []string
	for _, name := range kustomizationNames {
		p := filepath.Join(dir, name)
		if _, err := os.Lstat(p); err == nil {
			found = append(found, p)
		} else if !isMissing(err) {
			return "", gateSite{file: g.rel(p)}.unchecked("", "", "it cannot be read ("+errReason(err)+")")
		}
	}
	switch len(found) {
	case 0:
		return "", gateVerdict{}
	case 1:
		return found[0], gateVerdict{}
	}
	return "", gateSite{file: g.rel(found[0])}.unchecked("", "", "the directory holds more than one kustomization file")
}

// readYAML reads a file of the overlay, within what is left of the ceilings.
func (g *gate) readYAML(file string) (*yaml.Node, string) {
	data, reason := readGateFile(file, min(g.lim.FileBytes, g.lim.TotalBytes-g.read))
	if reason != "" {
		return nil, reason
	}
	g.read += int64(len(data))
	return parseGateYAML(data)
}

// clipLen is how many characters of a name from the repository a message keeps.
const clipLen = 200

// clip is s cut to clipLen characters, with an ellipsis when it was longer: a
// field, a reference or a kind is the repository's own text, of any length.
func clip(s string) string {
	if utf8.RuneCountInString(s) <= clipLen {
		return s
	}
	return string([]rune(s)[:clipLen]) + "…"
}

func join(prefix, name string) string {
	if prefix == "" {
		return name
	}
	return prefix + "." + name
}

func isNull(n *yaml.Node) bool { return n.Kind == yaml.ScalarNode && n.Tag == "!!null" }

// apply judges the value n of field by r.
func (g *gate) apply(r gateRule, n *yaml.Node, field string, s gateSite) gateVerdict {
	if isNull(n) || r.kind == gateData {
		return gateVerdict{}
	}
	switch r.kind {
	case gateList:
		return g.applyList(r, n, field, s)
	case gateMap:
		return g.applyMap(r, n, field, s, false)
	case gateNever:
		return g.applyNever(n, field, s)
	case gatePatch:
		if n.Kind == yaml.MappingNode { // inline, as data; kustomize rejects it
			return gateVerdict{}
		}
	}
	if n.Kind != yaml.ScalarNode || n.Tag != "!!str" {
		return s.unchecked(field, "", "a reference that is not a string")
	}
	return g.applyString(r.kind, n.Value, field, s)
}

func (g *gate) applyList(r gateRule, n *yaml.Node, field string, s gateSite) gateVerdict {
	if n.Kind != yaml.SequenceNode {
		return s.unchecked(field, "", "a value that is not a list")
	}
	for i, e := range n.Content {
		if v := g.apply(*r.elem, e, fmt.Sprintf("%s[%d]", field, i), s); v.Kind != gateOK {
			return v
		}
	}
	return gateVerdict{}
}

// applyMap judges the entries of a mapping. closed is the kustomization itself,
// where a field that kustomizationRules does not list is refused; elsewhere an
// entry no rule lists holds no reference.
func (g *gate) applyMap(r gateRule, n *yaml.Node, field string, s gateSite, closed bool) gateVerdict {
	if n.Kind != yaml.MappingNode {
		return s.unchecked(field, "", "a value that is not a mapping")
	}
	for i := 0; i+1 < len(n.Content); i += 2 {
		key := n.Content[i].Value
		sub, known := lookupRule(r.fields, key)
		if !known && closed {
			return s.unchecked(join(field, key), "", "a field that kustomize v5.8.3 does not have")
		}
		if !known {
			continue
		}
		if v := g.apply(sub, n.Content[i+1], join(field, key), s); v.Kind != gateOK {
			return v
		}
	}
	return gateVerdict{}
}

// applyNever refuses any value of a field that names a program to run or its
// arguments.
func (g *gate) applyNever(n *yaml.Node, field string, s gateSite) gateVerdict {
	var parts []string
	if n.Kind == yaml.ScalarNode {
		parts = append(parts, n.Value)
	}
	for _, c := range n.Content {
		parts = append(parts, c.Value)
	}
	ref := strings.Join(parts, " ")
	if ref == "" {
		return gateVerdict{}
	}
	return s.remote(field, ref, "it names a program to run or arguments for it")
}

func (g *gate) applyString(kind gateRuleKind, value, field string, s gateSite) gateVerdict {
	switch kind {
	case gateFileSource:
		parts := strings.Split(value, "=")
		if len(parts) > 2 {
			return s.unchecked(field, value, "a files entry with more than one equal sign")
		}
		return g.reference(parts[len(parts)-1], false, field, s)
	case gatePlugin:
		if strings.Contains(value, "\n") {
			return g.inlinePlugin(value, field, s)
		}
		return g.pluginPath(value, field, s)
	case gatePatch:
		if strings.Contains(value, "\n") {
			if inlineResources(value) {
				return gateVerdict{}
			}
			return s.unchecked(field, "", "text that is neither a path nor a patch")
		}
		return g.reference(value, false, field, s)
	}
	return g.reference(value, kind == gateBase, field, s)
}

// inlineResources reports whether text is what kustomize reads as an inline
// patch: documents that are Kubernetes objects.
func inlineResources(text string) bool {
	dec := yaml.NewDecoder(strings.NewReader(text))
	found := false
	for {
		var doc yaml.Node
		err := dec.Decode(&doc)
		if errors.Is(err, io.EOF) {
			return found
		}
		if err != nil || doc.Kind != yaml.DocumentNode || len(doc.Content) != 1 || !hasKey(doc.Content[0], "kind") {
			return false
		}
		found = true
	}
}

// hasKey reports whether n is a mapping with a key of exactly this name.
func hasKey(n *yaml.Node, name string) bool {
	return mapGet(n, name) != nil
}

// mapGet is the value of the key spelled exactly name in the mapping n.
func mapGet(n *yaml.Node, name string) *yaml.Node {
	if n == nil || n.Kind != yaml.MappingNode {
		return nil
	}
	for i := 0; i+1 < len(n.Content); i += 2 {
		if n.Content[i].Value == name {
			return n.Content[i+1]
		}
	}
	return nil
}

// reference judges one reference: it must be local, and below the limit once
// symbolic links are resolved. A directory is noted to be read in turn when
// follow says so.
func (g *gate) reference(ref string, follow bool, field string, s gateSite) gateVerdict {
	real, found, v := g.resolve(ref, field, s)
	if v.Kind != gateOK || !found {
		return v
	}
	// Only a regular file or a directory: kustomize blocks on a pipe.
	info, err := os.Stat(real)
	switch {
	case err != nil:
		return s.unchecked(field, ref, "it cannot be read ("+errReason(err)+")")
	case info.IsDir():
		if follow {
			g.bases = append(g.bases, real)
		}
	case !info.Mode().IsRegular():
		return s.unchecked(field, ref, "it is neither a regular file nor a directory")
	}
	return gateVerdict{}
}

// resolve turns a reference of the kustomization at s.dir into a real path. found
// is false for a path that is not there: kustomize reports it and fetches nothing.
func (g *gate) resolve(ref, field string, s gateSite) (real string, found bool, v gateVerdict) {
	if ref == "" {
		return "", false, gateVerdict{} // the directory of the kustomization itself
	}
	if ok, reason := localRef(ref); !ok {
		return "", false, s.remote(field, ref, reason)
	}
	cand := filepath.Join(s.dir, filepath.FromSlash(ref))
	if !within(g.root, cand) {
		return "", false, s.unchecked(field, ref, "it leaves "+g.limit)
	}
	real, err := filepath.EvalSymlinks(cand)
	switch {
	case isMissing(err):
		return "", false, gateVerdict{}
	case err != nil:
		return "", false, s.unchecked(field, ref, "it cannot be resolved ("+errReason(err)+")")
	case !within(g.root, real):
		return "", false, s.unchecked(field, ref, "it leaves "+g.limit+" through a symbolic link")
	}
	return real, true, gateVerdict{}
}

// pluginPath judges an entry of generators, transformers or validators that is
// not inline: a plugin configuration file. A directory is refused, not followed:
// kustomize reads the resources of its kustomization as plugin configurations
// (and runs what they say), where the gate reads them as resources.
func (g *gate) pluginPath(ref, field string, s gateSite) gateVerdict {
	real, found, v := g.resolve(ref, field, s)
	if v.Kind != gateOK || !found {
		return v
	}
	info, err := os.Stat(real)
	switch {
	case err != nil:
		return s.unchecked(field, ref, "it cannot be read ("+errReason(err)+")")
	case info.IsDir():
		return s.unchecked(field, ref, "a plugin directory cannot be checked")
	}
	file := gateSite{file: g.rel(real), dir: s.dir, depth: s.depth}
	node, reason := g.readYAML(real)
	if reason != "" {
		return file.unchecked("", "", reason)
	}
	return g.pluginConfig(node, "", file)
}

// inlinePlugin judges a plugin configuration written in the kustomization.
func (g *gate) inlinePlugin(text, field string, s gateSite) gateVerdict {
	node, reason := parseGateYAML([]byte(text))
	if reason != "" {
		return s.unchecked(field, "", "an inline plugin configuration: "+reason)
	}
	return g.pluginConfig(node, field, s)
}

// pluginConfig judges the configuration of a plugin: a builtin one of a known
// kind, that runs no function, whose fields that name a file are local.
func (g *gate) pluginConfig(node *yaml.Node, prefix string, s gateSite) gateVerdict {
	scalar := func(name string) string {
		if n := mapGet(node, name); n != nil && n.Kind == yaml.ScalarNode && n.Tag == "!!str" {
			return n.Value
		}
		return ""
	}
	if version := scalar("apiVersion"); version != "builtin" {
		return s.unchecked(join(prefix, "apiVersion"), "", fmt.Sprintf("a plugin of apiVersion %q: only builtin plugins are read", clip(version)))
	}
	kind := scalar("kind")
	fields, known := builtinPlugins[kind]
	if !known {
		return s.unchecked(join(prefix, "kind"), "", fmt.Sprintf("a builtin plugin of kind %q, which the gate does not know", clip(kind)))
	}
	if annotations := mapGet(mapGet(node, "metadata"), "annotations"); annotations != nil && annotations.Kind == yaml.MappingNode {
		for i := 0; i+1 < len(annotations.Content); i += 2 {
			for _, name := range functionAnnotations {
				if strings.EqualFold(annotations.Content[i].Value, name) {
					return s.unchecked(join(prefix, "metadata.annotations"), "", "a function annotation, which makes kustomize run a program")
				}
			}
		}
	}
	return g.apply(mapOf(fields), node, prefix, s)
}

func renderFailure(source, dialect, file, title string, from ToolSource, steps []string, repro string, err error) Finding {
	detail := failureDetail(err)
	first, _, _ := strings.Cut(detail, "\n")
	return Finding{
		ID:          K8sRenderID,
		Title:       title + ": " + first,
		Description: "The directory could not be rendered, so none of its resources were validated.",
		Message:     detail,
		Resolution:  renderResolution(source, from, detail),
		Steps:       steps,
		Repro:       repro,
		RanFrom:     from,
		Severity:    SeverityHigh,
		Source:      source,
		File:        file,
		IaCType:     dialect,
	}
}

// failureDetail is what a renderer printed when it failed, or the error itself.
func failureDetail(err error) string {
	var exitErr *exitError
	if errors.As(err, &exitErr) && exitErr.Stderr != "" {
		return strings.TrimSpace(exitErr.Stderr)
	}
	return err.Error()
}

// How to fix a chart or an overlay that does not render, in the renderer's own
// terms.
const (
	helmRenderResolution = "Render it locally with helm template and fix what it reports; " +
		"a chart's dependencies must be vendored in charts/ or fetched with helm dependency build."
	// remoteBlockedResolution is for an overlay whose remote base was refused
	// because the render runs with the network cut (DEVDESK-767).
	remoteBlockedResolution = "The overlay names a remote base (a git URL or an https resource) and DevDesk " +
		"renders a repository it does not trust with the network cut. Copy the base into the repository " +
		"and reference it by a relative path, or, for a repository you trust, set " +
		"scan.tools.kustomize.allow_remote_bases: true, which also lets the overlay reach the services of " +
		"this machine (its loopback)."
	// uncheckedResolution is for an overlay DevDesk did not build because it could
	// not check every reference in it (DEVDESK-771): kustomize is not started on
	// what it cannot judge.
	uncheckedResolution = "DevDesk reads an overlay before building it and builds it only when every reference " +
		"in it, and in what it pulls in, is a path of the repository. Remove what it could not read, or build " +
		"the overlay in a container (scan.tools.kustomize.source: image), which has no network, or, for a " +
		"repository you trust, set scan.tools.kustomize.allow_remote_bases: true, which also lets the overlay " +
		"reach the services of this machine (its loopback)."
	kustomizeRenderResolution = "Build it locally with kustomize build (or kubectl kustomize) and fix what it reports."
	// kustomize's load restrictor (LoadRestrictionsRootOnly, its default)
	// refuses a file outside the kustomization's directory, with this message.
	// The flag is not reserved (ToolKustomize.ReservedArgs) and lands after
	// `build` (afterSubcommand), where kustomize accepts it.
	loadRestrictorResolution = "kustomize refuses by default a file outside the overlay directory " +
		"(same as kubectl apply -k). Reference a directory with its own kustomization instead, " +
		"or, if your deployment tool allows it, set " +
		"scan.tools.kustomize.args: [--load-restrictor=LoadRestrictionsNone]."
)

// mountResolution is added for a kustomize image that could not find a path:
// the container sees only what DevDesk mounts (renderScope), and DevDesk does
// not walk the repository to tell a hidden reference from a broken one.
// ToolConfig's `source` key takes auto, binary or image.
const mountResolution = "If this reference points outside the directory DevDesk mounts into the container " +
	"(the scanned directory, or its git repository when it has one), scan the enclosing directory, " +
	"or set scan.tools.kustomize.source: binary (the binary sees the whole file system)."

// renderResolution picks the advice for a render failure from the renderer,
// where it ran and what it printed.
func renderResolution(source string, from ToolSource, detail string) string {
	if source != SourceKustomize {
		return helmRenderResolution
	}
	advice := kustomizeRenderResolution
	if isLoadRestrictor(detail) {
		advice = loadRestrictorResolution
	}
	if from == ToolSourceContainer &&
		(strings.Contains(detail, "evalsymlink failure") || strings.Contains(detail, "no such file or directory")) {
		advice += " " + mountResolution
	}
	return advice
}

// helmOrigins maps each rendered resource, by kind and name, to the template
// it came from, relative to the repository. helm names the template under the
// chart's own name, which need not be its directory's.
func helmOrigins(rendered []byte, chart string) map[string]string {
	origins := map[string]string{}
	for _, doc := range splitYAMLDocuments(rendered) {
		var source string
		for _, line := range strings.Split(doc, "\n") {
			if m := helmSourceLine.FindStringSubmatch(line); m != nil {
				source = m[1]
				break
			}
		}
		if source == "" {
			continue
		}
		var meta struct {
			Kind     string `yaml:"kind"`
			Metadata struct {
				Name string `yaml:"name"`
			} `yaml:"metadata"`
		}
		if yaml.Unmarshal([]byte(doc), &meta) != nil || meta.Kind == "" {
			continue
		}
		key := meta.Kind + "/" + meta.Metadata.Name
		if _, seen := origins[key]; seen {
			continue
		}
		_, rest, _ := strings.Cut(source, "/")
		origins[key] = path.Join(chart, rest)
	}
	return origins
}

// splitYAMLDocuments splits a multi-document stream on its `---` separators.
func splitYAMLDocuments(stream []byte) []string {
	var docs []string
	var cur strings.Builder
	r := bufio.NewReader(bytes.NewReader(stream))
	for {
		line, err := r.ReadString('\n')
		if strings.TrimRight(line, "\r\n") == "---" {
			docs = append(docs, cur.String())
			cur.Reset()
		} else {
			cur.WriteString(line)
		}
